input.command:
cd /home/user/guidebook
python3 - <<'PY'
import yaml, glob, collections
recs=[]
for f in sorted(glob.glob('_archived/data/jurisdictional_values/*.yaml')):
    d=yaml.safe_load(open(f)) or {}
    for r in (d.get('records') or []): recs.append(r)
print(f"=== {len(recs)} archived records ===")
cols=collections.Counter()
for r in recs:
    for k,v in r.items():
        if v not in (None,''): cols[k]+=1
print("non-null population per column:")
for k,v in sorted(cols.items(), key=lambda x:-x[1]): print(f"   {k:20s} {v}/{len(recs)}")
print("\n=== how much is item-DEPENDENT vs item-INDEPENDENT? ===")
pairs={(r.get('jurisdiction'), r.get('standard_name')) for r in recs}
print(f"   distinct (jurisdiction, standard_name) pairs: {len(pairs)}")
print(f"   distinct standard_name:                      {len({r.get('standard_name') for r in recs})}")
print(f"   distinct item_code:                          {len({r.get('item_code') for r in recs})}")
print(f"   distinct jurisdiction:                       {sorted({r.get('jurisdiction') for r in recs})}")
print("\n   -> collapsing on (jurisdiction, standard_name) discards ONLY the item link:")
print(f"      {len(recs)} rows -> {len(pairs)} leads  ({len(recs)-len(pairs)} are item-crossing duplicates)")
print("\n=== sample of the distinct leads ===")
for p in sorted(pairs, key=lambda x:(str(x[0]),str(x[1])))[:14]: print("   ",p)
PY

