import json, glob, os
D="/root/.claude/projects/-home-user-guidebook/6a6f63cd-b4d8-5e57-9230-c5afb931a48a/subagents"
rows=[]
for f in glob.glob(D+"/agent-*.jsonl"):
    ts=None; role=None
    with open(f, errors="replace") as fh:
        for l in fh:
            try: d=json.loads(l)
            except: continue
            ts = ts or d.get("timestamp")
            m=d.get("message") or {}
            c=m.get("content")
            txt = c if isinstance(c,str) else " ".join(x.get("text","") for x in c if isinstance(x,dict)) if isinstance(c,list) else ""
            if txt and role is None:
                up=txt[:200].upper()
                for r in ("AGONIST","ANTAGONIST","TRACER"):
                    if r in up: role=r; break
                else: role=txt[:44].replace("\n"," ")
            if ts and role: break
    if ts and ts.startswith("2026-09-02"):
        rows.append((ts, role, os.path.getsize(f)//1024, os.path.basename(f)))
for r in sorted(rows): print(f"{r[0][11:19]}  {str(r[1])[:40]:<40} {r[2]:>5}K  {r[3]}")
PY

